<x-layouts.app :title="$integration->exists?'Edit integration':'Create integration'"><x-page-header eyebrow="External connection" :title="$integration->exists?'Edit '.$integration->name:'Create integration'" description="Credentials are encrypted and never displayed again after saving." />@if($errors->any())<x-alert variant="danger" class="mt-5"><ul>@foreach($errors->all() as $error)<li>{{ $error }}</li>@endforeach</ul></x-alert>@endif<form class="mt-6 space-y-6" method="post" action="{{ $integration->exists?route('tenant.integrations.update',$integration):route('tenant.integrations.store') }}" x-data="{provider:'{{ old('provider',$integration->provider instanceof \BackedEnum?$integration->provider->value:$integration->provider) }}'}">@csrf @if($integration->exists)@method('put')@endif<section class="panel"><h2 class="section-title">Connection</h2><div class="mt-4 grid gap-4 sm:grid-cols-2"><label class="field-label">Name<input class="input mt-1" name="name" required maxlength="120" value="{{ old('name',$integration->name) }}"></label><label class="field-label">Provider<select class="input mt-1" name="provider" x-model="provider"><option value="generic_api">Generic REST / Laravel ERP</option><option value="webhook">Outbound webhook</option><option value="wordpress">WordPress</option><option value="woocommerce">WooCommerce</option></select></label><label class="field-label" x-show="provider==='generic_api'||provider==='wordpress'">Base URL<input class="input mt-1" name="base_url" type="url" value="{{ old('base_url',data_get($integration->configuration,'base_url')) }}" placeholder="https://erp.example.com"></label><label class="field-label" x-show="provider==='webhook'">Destination URL<input class="input mt-1" name="destination_url" type="url" value="{{ old('destination_url',data_get($integration->configuration,'destination_url')) }}" placeholder="https://example.com/webhooks"></label><label class="field-label" x-show="provider==='woocommerce'">Store URL<input class="